// Independent replay of twelve accepted-source streams and exact EC matrix closure.
// Does not import producer arithmetic, parser, filter, or rank code.
use std::collections::HashMap;
use std::fs;
const P:i64=4001;const R:i64=4019;const F:usize=8;const L:usize=16;const T:usize=24;const B:usize=25;
const SEEDS:[u64;3]=[0xb2eaea9161bd7845,0x8245ccebbea61468,0xa735ae5ce2664101];
#[derive(Clone,Copy,Debug,Eq,PartialEq,Hash)]enum Pt{O,A(i64,i64)}
fn red(x:i64,n:i64)->i64{x.rem_euclid(n)}
fn inv(x:i64,n:i64)->i64{let(mut a,mut b,mut u,mut v)=(red(x,n),n,1,0);while b!=0{let q=a/b;(a,b)=(b,a-q*b);(u,v)=(v,u-q*v)}assert_eq!(a,1);red(u,n)}
fn add(x:Pt,y:Pt)->Pt{match(x,y){(Pt::O,z)|(z,Pt::O)=>z,(Pt::A(a,b),Pt::A(c,d))=>{if a==c&&red(b+d,P)==0{return Pt::O}let slope=if a==c{red((3*a*a+1)*inv(2*b,P),P)}else{red((d-b)*inv(c-a,P),P)};let u=red(slope*slope-a-c,P);Pt::A(u,red(slope*(a-u)-b,P))}}}
fn mul(mut n:i64,mut x:Pt)->Pt{if n<0{n=-n;x=match x{Pt::O=>Pt::O,Pt::A(a,b)=>Pt::A(a,red(-b,P))}}let mut z=Pt::O;while n>0{if n&1!=0{z=add(z,x)}x=add(x,x);n>>=1}z}
fn base()->Vec<Pt>{let mut v=Vec::new();for x in 0..P{for y in 0..P{if red(y*y-x*x*x-x-27,P)==0{v.push(Pt::A(x,y));break}}if v.len()==F+L{break}}v}
fn next(s:&mut u64)->u64{*s^=*s<<13;*s^=*s>>7;*s^=*s<<17;*s}
#[derive(Clone,Debug)]struct Src{trial:usize,a:i64,b:i64,r:Pt,kind:usize,i:usize,j:usize,row:Vec<i64>}
fn entries(base:&[Pt],arm:usize)->HashMap<Pt,(usize,usize,usize)>{let mut h=HashMap::new();for i in 0..F{for j in i..F{h.entry(add(base[i],base[j])).or_insert((0,i,j));}}if arm==1{for i in 0..F{for j in F..F+L{h.entry(add(base[i],base[j])).or_insert((1,i,j));}}for i in F..F+L{for j in i..F+L{h.entry(add(base[i],base[j])).or_insert((2,i,j));}}}h}
fn parse(line:&str)->Src{let t:Vec<_>=line.split_whitespace().collect();assert_eq!(t.len(),10);let trial=t[2][6..].parse().unwrap();let a=t[3][2..].parse().unwrap();let b:i64=t[4][2..].parse().unwrap();let x=t[5][4..].trim_end_matches(',').parse().unwrap();let y=t[6].trim_end_matches(')').parse().unwrap();let kind=match &t[7][5..]{"Full"=>0,"One"=>1,"Two"=>2,_=>panic!("kind")};let i=t[8][2..].parse().unwrap();let j=t[9][2..].parse().unwrap();let mut row=vec![0;B+1];row[i]+=1;row[j]+=1;row[T]=red(-b,R);row[B]=a;Src{trial,a,b,r:Pt::A(x,y),kind,i,j,row}}
fn read(path:&str)->(Vec<Src>,Vec<Src>,Vec<(usize,usize,usize,i64)>){let raw=fs::read_to_string(path).unwrap();assert!(raw.lines().last().unwrap().starts_with("RUN_OK=1 case="));let mut blocks=[Vec::new(),Vec::new()];let mut arm=0;let mut started=false;let mut summaries=Vec::new();for line in raw.lines(){if line.starts_with("source "){let id:usize=line.split_whitespace().nth(1).unwrap()[3..].parse().unwrap();if id==0&&started{arm+=1}started=true;assert!(arm<2);assert_eq!(id,blocks[arm].len());blocks[arm].push(parse(line))}else if line.starts_with("arm="){let mut count=0;let mut rb=0;let mut ra=0;let mut d=-1;for field in line.split_whitespace(){if let Some(v)=field.strip_prefix("complete_rows="){count=v.parse().unwrap()}if let Some(v)=field.strip_prefix("rank_base="){rb=v.parse().unwrap()}if let Some(v)=field.strip_prefix("rank_aug="){ra=v.parse().unwrap()}if let Some(v)=field.strip_prefix("recovered="){d=v.parse().unwrap()}}summaries.push((count,rb,ra,d))}}assert_eq!(arm,1);assert_eq!(summaries.len(),2);(blocks[0].clone(),blocks[1].clone(),summaries)}
fn rank_answer(rows:&[Vec<i64>],with_target:bool)->(usize,Option<i64>){let n=if with_target{F+1}else{F};let mut z:Vec<Vec<i64>>=rows.iter().map(|r|{let mut x=r[..F].to_vec();if with_target{x.push(r[T])}x.push(r[B]);x}).collect();let mut rank=0;for j in 0..n{if let Some(k)=(rank..z.len()).find(|&k|z[k][j]!=0){z.swap(rank,k);let zinv=inv(z[rank][j],R);for h in j..=n{z[rank][h]=red(z[rank][h]*zinv,R)}let pivot=z[rank].clone();for k in 0..z.len(){if k!=rank{let c=z[k][j];if c!=0{for h in j..=n{z[k][h]=red(z[k][h]-c*pivot[h],R)}}}}rank+=1}}let ans=if with_target{z.iter().find(|r|r[..F].iter().all(|&v|v==0)&&r[F]!=0).map(|r|red(r[n]*inv(r[F],R),R))}else{None};(rank,ans)}
fn filter(src:&[Src],base:&[Pt],q:Pt,g:Pt)->Vec<Vec<i64>>{let mut pivots:Vec<Option<Vec<i64>>>=vec![None;L];let mut out=Vec::new();for s in src{let mut row=s.row.clone();let mut placed=false;for j in F..F+L{if row[j]==0{continue}if let Some(p)=&pivots[j-F]{let z=row[j];for k in 0..=B{row[k]=red(row[k]-z*p[k],R)}}else{let z=inv(row[j],R);for v in &mut row{*v=red(*v*z,R)}pivots[j-F]=Some(row.clone());placed=true;break}}if !placed{assert!(row[F..T].iter().all(|&v|v==0));let mut lhs=Pt::O;for j in 0..T{lhs=add(lhs,mul(row[j],base[j]))}lhs=add(lhs,mul(row[T],q));assert_eq!(lhs,mul(row[B],g));out.push(row)}}out}
